from .weights import weights

def pool(h, w, temperature=2.0):
    h_unit = h / h.norm(dim=-1, keepdim=True).clamp_min(1e-12)
    score_tmp = h_unit @ w
    alpha_tmp = weights(score_tmp, temperature)
    return (alpha_tmp.unsqueeze(-1) * h_unit).sum(dim=0)

